#include <iostream>
using namespace std;
long long C(int n, int k) {
    if (k > n) return 0;
    long long res = 1;
    for (int i = 1; i <= k; i++)
        res = res * (n - i + 1) / i;   // 边乘边除，防溢出
    return res;
}
int main() {
    int n, k;
    cin >> n >> k;
    cout << C(n, k) << endl;           // C(n,k)
    return 0;
}

#include <iostream>
using namespace std;
int a[20][20];
int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        a[i][0] = a[i][i] = 1;                    // 首尾是 1
        for (int j = 1; j < i; j++)
            a[i][j] = a[i-1][j-1] + a[i-1][j];    // 上面两个相加
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= i; j++) cout << a[i][j] << " ";
        cout << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;
long long powmod(long long a, long long b, long long m) {
    long long res = 1;
    while (b > 0) {
        if (b & 1) res = res * a % m;   // 这一位是 1 就乘上去
        a = a * a % m;                  // 底数平方（翻倍）
        b >>= 1;                        // 指数右移一位
    }
    return res;
}
int main() {
    long long a, b, m;
    cin >> a >> b >> m;
    cout << powmod(a, b, m) << endl;   // a^b mod m
    return 0;
}

